const MAINT=[['Brasileirão',/brasileir/],['Champions League',/champions/],['Copa América',/copa america/],['Eurocopa',/eurocopa/],['Libertadores',/libertadores/],['Liga Europa',/liga europa/],['Sul-Americana',/sul.?americana/],['Copa do Mundo',/copa do mundo/]],mainOf=n=>{const x=String(n).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),m=MAINT.find(([,r])=>r.test(x));return m?m[0]:null};
const R={};ps.forEach(p=>R[p]={c:0,i:0,o:0,n:{},m:{}});all.forEach(t=>(t.players||[]).forEach(n=>{const p=cn(n),o=R[p]||(R[p]={c:0,i:0,o:0,n:{},m:{}});t.kind=='i'?o.i++:o.c++;o.n[t.name]=(o.n[t.name]||0)+1;if(t.kind!='i'){const mk=mainOf(t.name);mk?o.m[mk]=(o.m[mk]||0)+1:o.o++}}));
const tot=o=>o.c+o.i,CD=ind?[...new Set(all.map(t=>t.name))].sort((a,b)=>a.localeCompare(b)).map(c=>({k:'n:'+c,l:c,v:o=>o.n[c]||0})):[...MAINT.map(([c])=>({k:'m:'+c,l:c,v:o=>o.m[c]||0})),{k:'o',l:'Outros',v:o=>o.o},...(gen?[{k:'i',l:'Prêmios individuais',v:o=>o.i}]:[])];CD.push({k:'tot',l:'Total',v:tot,b:1});
